{% set w = 'sensor.deadline_window' %}
{{ {
  'goal': states('input_select.house_battery_deadline_goal'),
  'target_soc': states('input_number.house_battery_deadline_target_soc') | float(0),
  'target_energy': states('input_number.house_battery_deadline_target_energy') | float(0),
  'fallback': states('input_select.house_battery_deadline_reached'),
  'hold_after_target': is_state('input_boolean.house_battery_deadline_hold_after_target', 'on'),
  'reserve_pv': is_state('input_boolean.house_battery_deadline_reserve_pv', 'on'),
  'pv_forecast_kwh': states('sensor.solar_forecast_surplus_today') | float(0),
  'window': {'attributes': {
      'pacing': state_attr(w, 'pacing'),
      'configured': state_attr(w, 'configured'),
      'in_window': state_attr(w, 'in_window'),
      'minutes_left': state_attr(w, 'minutes_left') | int(0),
      'start': state_attr(w, 'start'),
      'end': state_attr(w, 'end'),
      'blocks': state_attr(w, 'blocks') or [],
      'now_hms': now().strftime('%H:%M:%S')
  }}
} | to_json }}

