// Publish the settings snapshot to flow context.
// The control path reads ONLY this - it runs on every P1 update (up to ~1 Hz) and used to
// walk seven api-current-state nodes in series to fetch values that change when the user
// touches a dashboard, i.e. almost never.
//
// A bad render keeps the PREVIOUS snapshot rather than blanking it, so one failed refresh
// is harmless; Compute plan gives up on its own once the snapshot goes stale (5 minutes).
const cfg = msg.deadline_cfg;
const ok = cfg && typeof cfg === 'object' && cfg.window
    && typeof cfg.window === 'object' && cfg.window.attributes;
if (!ok) {
    node.status({ fill: 'red', shape: 'ring', text: `settings render failed ${new Date().toLocaleTimeString()}` });
    node.warn('[Deadline] settings template returned nothing usable - keeping the previous snapshot');
    return null;
}
cfg.stamp = Date.now();
flow.set('deadline_cfg', cfg);
const a = cfg.window.attributes;
node.status({ fill: 'grey', shape: 'dot', text: `${cfg.goal || '?'} / ${a.pacing || '?'} @ ${new Date().toLocaleTimeString()}` });
return null;                         // a settings refresh never continues into the flow
